import React, { useState } from 'react';
import { Card } from './shared/Card';
import { Icon } from './shared/Icon';

type TaskCategory = 'Pre-Departure' | 'In-Saudi' | 'Post-Return';

interface OpsTask {
  id: string;
  title: string;
  category: TaskCategory;
  dueDate: string;
  completed: boolean;
  assignee: string;
}

const MOCK_TASKS: OpsTask[] = [
  { id: '1', title: 'Submit Visa Applications', category: 'Pre-Departure', dueDate: '2025-03-01', completed: true, assignee: 'Abdullah' },
  { id: '2', title: 'Finalize Rooming List', category: 'Pre-Departure', dueDate: '2025-03-10', completed: false, assignee: 'Siti' },
  { id: '3', title: 'Distribute ID Cards & Batik', category: 'Pre-Departure', dueDate: '2025-03-12', completed: false, assignee: 'Budi' },
  { id: '4', title: 'Check-in Hotel Makkah', category: 'In-Saudi', dueDate: '2025-03-16', completed: false, assignee: 'Mutawif' },
  { id: '5', title: 'Collect Feedback Forms', category: 'Post-Return', dueDate: '2025-03-28', completed: false, assignee: 'Admin' },
];

const OpsCenter: React.FC = () => {
  const [selectedKloter, setSelectedKloter] = useState('Kloter A');
  const [tasks, setTasks] = useState<OpsTask[]>(MOCK_TASKS);
  const [activeTab, setActiveTab] = useState<TaskCategory>('Pre-Departure');
  const [newTaskTitle, setNewTaskTitle] = useState('');

  const filteredTasks = tasks.filter(t => t.category === activeTab);

  const toggleTask = (id: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const addTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    const newTask: OpsTask = {
      id: Date.now().toString(),
      title: newTaskTitle,
      category: activeTab,
      dueDate: new Date().toISOString().split('T')[0],
      completed: false,
      assignee: 'Unassigned'
    };

    setTasks([...tasks, newTask]);
    setNewTaskTitle('');
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const calculateProgress = (category: TaskCategory) => {
    const categoryTasks = tasks.filter(t => t.category === category);
    if (categoryTasks.length === 0) return 0;
    const completed = categoryTasks.filter(t => t.completed).length;
    return Math.round((completed / categoryTasks.length) * 100);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-bold text-green-900">Operations Center</h2>
           <p className="text-gray-500 text-sm">Manage logistics, checklists, and workflows for your groups.</p>
        </div>
        <div className="flex items-center bg-white rounded-lg shadow-sm px-3 py-2 border border-gray-200">
           <Icon name="users" className="h-5 w-5 text-gray-500 mr-2" />
           <select 
             value={selectedKloter} 
             onChange={(e) => setSelectedKloter(e.target.value)}
             className="bg-transparent border-none focus:ring-0 text-gray-700 font-medium text-sm outline-none cursor-pointer"
           >
             <option value="Kloter A">Kloter A - 15 Mar 2025</option>
             <option value="Kloter B">Kloter B - 20 Apr 2025</option>
             <option value="Kloter C">Kloter C - 10 Jun 2025</option>
           </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {(['Pre-Departure', 'In-Saudi', 'Post-Return'] as TaskCategory[]).map(cat => {
            const progress = calculateProgress(cat);
            const isActive = activeTab === cat;
            return (
             <Card key={cat} className={`cursor-pointer transition-all hover:shadow-lg ${isActive ? 'ring-2 ring-green-500 bg-green-50/50' : ''}`} >
                <div onClick={() => setActiveTab(cat)}>
                   <div className="flex justify-between items-start mb-4">
                      <h3 className={`font-semibold ${isActive ? 'text-green-900' : 'text-gray-700'}`}>{cat}</h3>
                      {isActive && <div className="h-2 w-2 rounded-full bg-green-500"></div>}
                   </div>
                   <div className="flex items-end justify-between">
                      <span className="text-3xl font-bold text-green-800">{progress}%</span>
                      <span className="text-xs text-gray-500 mb-1">Completed</span>
                   </div>
                   <div className="w-full bg-gray-200 rounded-full h-1.5 mt-3">
                      <div className="bg-green-600 h-1.5 rounded-full transition-all duration-500" style={{ width: `${progress}%` }}></div>
                   </div>
                </div>
             </Card>
        )})}
      </div>

      <Card>
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-6 gap-4">
           <h3 className="text-lg font-bold text-gray-800 flex items-center">
              <span className="bg-green-100 p-1.5 rounded-md mr-3">
                 <Icon name="ops" className="h-5 w-5 text-green-700"/>
              </span>
              {activeTab} Checklist
           </h3>
           <div className="flex items-center space-x-2">
                <span className="text-xs font-medium text-gray-500 px-3 py-1 bg-gray-100 rounded-full">
                    {filteredTasks.filter(t => t.completed).length}/{filteredTasks.length} Done
                </span>
           </div>
        </div>

        <form onSubmit={addTask} className="flex gap-2 mb-6">
           <input 
             type="text" 
             placeholder="Add a new task..." 
             className="flex-1 border border-gray-300 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-green-500 focus:border-transparent text-sm"
             value={newTaskTitle}
             onChange={(e) => setNewTaskTitle(e.target.value)}
           />
           <button type="submit" className="bg-green-800 text-white px-4 py-2 rounded-lg hover:bg-green-900 transition-colors flex items-center text-sm font-medium">
              <Icon name="add" className="h-4 w-4 mr-1" /> Add
           </button>
        </form>

        <div className="space-y-3">
           {filteredTasks.length === 0 ? (
               <div className="text-center py-12 border-2 border-dashed border-gray-100 rounded-xl">
                  <Icon name="document" className="h-10 w-10 text-gray-300 mx-auto mb-2" />
                  <p className="text-gray-400 text-sm">No tasks found for this phase.</p>
               </div>
           ) : (
               filteredTasks.map(task => (
                   <div key={task.id} className={`flex items-center p-3 rounded-lg border transition-all group ${task.completed ? 'bg-gray-50 border-gray-100' : 'bg-white border-gray-200 hover:border-green-300 shadow-sm'}`}>
                       <button 
                         onClick={() => toggleTask(task.id)}
                         className={`flex-shrink-0 h-5 w-5 rounded border mr-4 flex items-center justify-center transition-colors ${task.completed ? 'bg-green-600 border-green-600 text-white' : 'border-gray-300 bg-white text-transparent hover:border-green-500'}`}
                       >
                         <Icon name="check" className="w-3.5 h-3.5" />
                       </button>
                       <div className="flex-1 min-w-0">
                          <p className={`font-medium text-sm truncate ${task.completed ? 'text-gray-400 line-through' : 'text-gray-800'}`}>{task.title}</p>
                          <div className="flex flex-wrap items-center text-xs text-gray-500 mt-1 gap-3">
                             <span className="flex items-center bg-gray-100 px-2 py-0.5 rounded"><Icon name="users" className="h-3 w-3 mr-1 text-gray-400"/> {task.assignee}</span>
                             <span className={`flex items-center ${new Date(task.dueDate) < new Date() && !task.completed ? 'text-red-500 font-semibold' : ''}`}>
                                <Icon name="calendar" className="h-3 w-3 mr-1 text-gray-400" />
                                {task.dueDate}
                             </span>
                          </div>
                       </div>
                       <button onClick={() => deleteTask(task.id)} className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-red-500 p-2 transition-opacity">
                          <Icon name="delete" className="h-4 w-4" />
                       </button>
                   </div>
               ))
           )}
        </div>
      </Card>

       <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card>
              <h4 className="font-semibold text-gray-800 mb-4 flex items-center">
