import React, { useState } from 'react';
import { Icon } from './shared/Icon';

interface OpsBotProps {
  isOpen: boolean;
  setIsOpen: (isOpen: boolean) => void;
  onCommand?: (command: string) => string;
}

const OpsBot: React.FC<OpsBotProps> = ({ isOpen, setIsOpen, onCommand }) => {
  const [messages, setMessages] = useState([
    { from: 'bot', text: 'Assalamualaikum! Saya OpsBot. Ada yang bisa saya bantu terkait operasional umroh?' }
  ]);
  const [input, setInput] = useState('');

  const handleSend = () => {
    if (!input.trim()) return;
    const userMsg = { from: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);

    // Process command
    if (onCommand) {
        // Simulating a slight delay for "thinking"
        setTimeout(() => {
            const responseText = onCommand(input);
            setMessages(prev => [...prev, { from: 'bot', text: responseText }]);
        }, 500);
    } else {
        setTimeout(() => {
            setMessages(prev => [...prev, { from: 'bot', text: `Bot offline (No command handler).`}]);
        }, 500);
    }

    setInput('');
  };

  return (
    <>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-8 right-8 bg-green-800 text-white p-4 rounded-full shadow-lg hover:bg-green-900 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-700 transition-transform transform hover:scale-110 z-50"
      >
        <Icon name="bot" className="h-8 w-8" />
      </button>

      {isOpen && (
        <div className="fixed bottom-24 right-8 w-96 h-[32rem] bg-white rounded-xl shadow-2xl flex flex-col transition-all duration-300 z-50">
          <div className="bg-gradient-to-r from-green-800 to-green-700 text-white p-4 rounded-t-xl flex justify-between items-center">
            <div>
                <h3 className="font-bold text-lg">OpsBot Assistant</h3>
                <p className="text-xs text-green-200">AI Powered Operations</p>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-green-200 hover:text-white">
                <Icon name="close" className="h-6 w-6" />
            </button>
          </div>

          <div className="flex-1 p-4 overflow-y-auto bg-gray-50">
            <div className="space-y-4">
              {messages.map((msg, index) => (
                <div key={index} className={`flex ${msg.from === 'bot' ? 'justify-start' : 'justify-end'}`}>
                  <div className={`max-w-xs px-4 py-2 rounded-2xl ${msg.from === 'bot' ? 'bg-green-100 text-green-900 rounded-bl-none' : 'bg-yellow-400 text-yellow-900 rounded-br-none'}`}>
                    {msg.text}
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="p-4 border-t">
            <div className="flex items-center space-x-2">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Type 'Add task...' or 'Switch to Kloter A'"
                className="flex-1 px-4 py-2 border rounded-full focus:outline-none focus:ring-2 focus:ring-green-500 text-sm"
              />
              <button onClick={handleSend} className="bg-green-800 text-white p-2.5 rounded-full hover:bg-green-900">
                <Icon name="send" className="h-5 w-5" />
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default OpsBot;

import React, { useState } from 'react';
import { Card } from './shared/Card';
import { Icon } from './shared/Icon';
import { OpsTask, TaskCategory } from '../types';
import { TEAM_MEMBERS } from '../constants';

interface OpsCenterProps {
  tasks: OpsTask[];
  setTasks: React.Dispatch<React.SetStateAction<OpsTask[]>>;
  selectedKloter: string;
  setSelectedKloter: (kloter: string) => void;
}

const OpsCenter: React.FC<OpsCenterProps> = ({ tasks, setTasks, selectedKloter, setSelectedKloter }) => {
  const [activeTab, setActiveTab] = useState<TaskCategory>('Pre-Departure');
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskAssignee, setNewTaskAssignee] = useState('Abdullah');
  const [selectedTask, setSelectedTask] = useState<OpsTask | null>(null);

  const filteredTasks = tasks.filter(t => t.category === activeTab);

  const toggleTask = (id: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
    if (selectedTask && selectedTask.id === id) {
        setSelectedTask(prev => prev ? { ...prev, completed: !prev.completed } : null);
    }
  };

  const updateTaskAssignee = (id: string, newAssignee: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, assignee: newAssignee } : t));
    if (selectedTask && selectedTask.id === id) {
        setSelectedTask(prev => prev ? { ...prev, assignee: newAssignee } : null);
    }
  };

  const updateTaskDescription = (id: string, newDescription: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, description: newDescription } : t));
    if (selectedTask && selectedTask.id === id) {
        setSelectedTask(prev => prev ? { ...prev, description: newDescription } : null);
    }
  };

  const addTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    const newTask: OpsTask = {
      id: Date.now().toString(),
      title: newTaskTitle,
      category: activeTab,
      dueDate: new Date().toISOString().split('T')[0],
      completed: false,
      assignee: newTaskAssignee,
      description: ''
    };

    setTasks([...tasks, newTask]);
    setNewTaskTitle('');
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
    if (selectedTask?.id === id) setSelectedTask(null);
  };

  const calculateProgress = (category: TaskCategory) => {
    const categoryTasks = tasks.filter(t => t.category === category);
    if (categoryTasks.length === 0) return 0;
    const completed = categoryTasks.filter(t => t.completed).length;
    return Math.round((completed / categoryTasks.length) * 100);
  };

  const toggleTaskCompletionFromModal = () => {
      if (!selectedTask) return;
      toggleTask(selectedTask.id);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-bold text-green-900">Operations Center</h2>
           <p className="text-gray-500 text-sm">Manage logistics, checklists, and workflows for your groups.</p>
        </div>
        <div className="flex items-center bg-white rounded-lg shadow-sm px-3 py-2 border border-gray-200">
           <Icon name="users" className="h-5 w-5 text-gray-500 mr-2" />
           <select 
             value={selectedKloter} 
             onChange={(e) => setSelectedKloter(e.target.value)}
             className="bg-transparent border-none focus:ring-0 text-gray-700 font-medium text-sm outline-none cursor-pointer"
           >
             <option value="Kloter A">Kloter A - 15 Mar 2025</option>
             <option value="Kloter B">Kloter B - 20 Apr 2025</option>
             <option value="Kloter C">Kloter C - 10 Jun 2025</option>
           </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {(['Pre-Departure', 'In-Saudi', 'Post-Return'] as TaskCategory[]).map(cat => {
            const progress = calculateProgress(cat);
            const isActive = activeTab === cat;
            return (
             <Card key={cat} className={`cursor-pointer transition-all hover:shadow-lg ${isActive ? 'ring-2 ring-green-500 bg-green-50/50' : ''}`} >
                <div onClick={() => setActiveTab(cat)}>
                   <div className="flex justify-between items-start mb-4">
                      <h3 className={`font-semibold ${isActive ? 'text-green-900' : 'text-gray-700'}`}>{cat}</h3>
                      {isActive && <div className="h-2 w-2 rounded-full bg-green-500"></div>}
                   </div>
                   <div className="flex items-end justify-between">
                      <span className="text-3xl font-bold text-green-800">{progress}%</span>
                      <span className="text-xs text-gray-500 mb-1">Completed</span>
                   </div>
                   <div className="w-full bg-gray-200 rounded-full h-1.5 mt-3">
                      <div className="bg-green-600 h-1.5 rounded-full transition-all duration-500" style={{ width: `${progress}%` }}></div>
                   </div>
                </div>
             </Card>
        )})}
      </div>

      <Card>
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-6 gap-4">
           <h3 className="text-lg font-bold text-gray-800 flex items-center">
              <span className="bg-green-100 p-1.5 rounded-md mr-3">
                 <Icon name="ops" className="h-5 w-5 text-green-700"/>
              </span>
              {activeTab} Checklist
           </h3>
           <div className="flex items-center space-x-2">
                <span className="text-xs font-medium text-gray-500 px-3 py-1 bg-gray-100 rounded-full">
                    {filteredTasks.filter(t => t.completed).length}/{filteredTasks.length} Done
                </span>
           </div>
        </div>

        <form onSubmit={addTask} className="flex flex-col md:flex-row gap-3 mb-6 bg-gray-50 p-4 rounded-lg border border-gray-100">
           <div className="flex-1">
               <input 
                type="text" 
                placeholder="What needs to be done?" 
                className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-green-500 focus:border-transparent text-sm"
                value={newTaskTitle}
                onChange={(e) => setNewTaskTitle(e.target.value)}
                />
           </div>
           <div className="flex gap-2 w-full md:w-auto">
               <select
                    value={newTaskAssignee}
                    onChange={(e) => setNewTaskAssignee(e.target.value)}
                    className="border border-gray-300 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-green-500 focus:border-transparent text-sm bg-white cursor-pointer"
                >
                    {TEAM_MEMBERS.map(member => (
                    <option key={member} value={member}>{member}</option>
                    ))}
                </select>
               <button type="submit" className="bg-green-800 text-white px-4 py-2 rounded-lg hover:bg-green-900 transition-colors flex items-center justify-center text-sm font-medium whitespace-nowrap">
                  <Icon name="add" className="h-4 w-4 mr-1" /> Add Task
               </button>
           </div>
        </form>

        <div className="space-y-3">
           {filteredTasks.length === 0 ? (
               <div className="text-center py-12 border-2 border-dashed border-gray-100 rounded-xl">
                  <Icon name="document" className="h-10 w-10 text-gray-300 mx-auto mb-2" />
                  <p className="text-gray-400 text-sm">No tasks found for this phase.</p>
               </div>
           ) : (
               filteredTasks.map(task => (
                   <div key={task.id} className={`flex items-center p-3 rounded-lg border transition-all group ${task.completed ? 'bg-gray-50 border-gray-100' : 'bg-white border-gray-200 hover:border-green-300 shadow-sm'}`}>
                       <button 
                         onClick={(e) => {
                             e.stopPropagation();
                             toggleTask(task.id);
                         }}
                         className={`flex-shrink-0 h-5 w-5 rounded border mr-4 flex items-center justify-center transition-colors ${task.completed ? 'bg-green-600 border-green-600 text-white' : 'border-gray-300 bg-white text-transparent hover:border-green-500'}`}
                       >
                         <Icon name="check" className="w-3.5 h-3.5" />
                       </button>
                       <div className="flex-1 min-w-0 cursor-pointer hover:opacity-80" onClick={() => setSelectedTask(task)}>
                          <p className={`font-medium text-sm truncate ${task.completed ? 'text-gray-400 line-through' : 'text-gray-800'}`}>{task.title}</p>
                          <div className="flex flex-wrap items-center text-xs text-gray-500 mt-1 gap-3">
                             <div className="flex items-center bg-gray-100 pl-2 rounded hover:bg-white border border-transparent hover:border-gray-200 transition-colors" onClick={(e) => e.stopPropagation()}>
                                <Icon name="users" className="h-3 w-3 mr-1 text-gray-400"/> 
                                <select 
                                    value={task.assignee}
                                    onChange={(e) => updateTaskAssignee(task.id, e.target.value)}
                                    className="bg-transparent border-none text-xs text-gray-600 font-medium py-0.5 pr-2 focus:ring-0 cursor-pointer outline-none"
                                >
                                    {TEAM_MEMBERS.map(m => <option key={m} value={m}>{m}</option>)}
                                </select>
                             </div>
                             <span className={`flex items-center ${new Date(task.dueDate) < new Date() && !task.completed ? 'text-red-500 font-semibold' : ''}`}>
                                <Icon name="calendar" className="h-3 w-3 mr-1 text-gray-400" />
                                {task.dueDate}
                             </span>
                          </div>
                       </div>
                       <button onClick={(e) => { e.stopPropagation(); deleteTask(task.id); }} className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-red-500 p-2 transition-opacity">
                          <Icon name="delete" className="h-4 w-4" />
                       </button>
                   </div>
               ))
           )}
        </div>
      </Card>

      {/* Task Detail Modal */}
      {selectedTask && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4" onClick={() => setSelectedTask(null)}>
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center p-5 border-b border-gray-100">
                     <div className="flex items-center space-x-3">
                         <div className={`p-2 rounded-lg ${selectedTask.completed ? 'bg-green-100' : 'bg-gray-100'}`}>
                             <Icon name={selectedTask.completed ? 'check' : 'ops'} className={`h-5 w-5 ${selectedTask.completed ? 'text-green-600' : 'text-gray-500'}`} />
                         </div>
                         <h3 className="font-bold text-lg text-gray-800">Task Details</h3>
                     </div>
                     <button onClick={() => setSelectedTask(null)} className="text-gray-400 hover:text-gray-600 p-1 hover:bg-gray-100 rounded-full transition-colors">
                        <Icon name="close" className="h-5 w-5"/>
                     </button>
                </div>
                <div className="p-6 space-y-6">
                     <div>
                        <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1 block">Title</span>
                        <p className="text-xl font-semibold text-gray-900 leading-snug">{selectedTask.title}</p>
                     </div>

                     <div className="grid grid-cols-2 gap-6">
                         <div className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider block mb-1">Status</span>
                            <div className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${selectedTask.completed ? 'bg-green-100 text-green-800' : 'bg-yellow-100 text-yellow-800'}`}>
                                {selectedTask.completed ? 'Completed' : 'Pending'}
                            </div>
                         </div>
                         <div className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider block mb-1">Due Date</span>
                            <p className="text-sm font-medium text-gray-700 flex items-center">
                                <Icon name="calendar" className="h-4 w-4 mr-2 text-gray-400"/>
                                {selectedTask.dueDate}
                            </p>
                         </div>
                     </div>

                     <div className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                        <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider block mb-2">Assignee</span>
                        <div className="flex items-center">
                            <div className="h-8 w-8 rounded-full bg-green-200 flex items-center justify-center text-green-800 text-sm font-bold mr-3 border-2 border-white shadow-sm">
                                {selectedTask.assignee.charAt(0)}
                            </div>
                            <div>
                                <p className="text-sm font-medium text-gray-900">{selectedTask.assignee}</p>
                                <p className="text-xs text-gray-500">Responsible for this task</p>
                            </div>
                        </div>
                     </div>

                     <div>
                        <div className="flex justify-between items-center mb-2">
                            <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider block">Description</span>
                             <span className="text-[10px] text-gray-400 italic">Auto-saved</span>
                        </div>
                        <textarea
                            className="w-full p-4 bg-gray-50 rounded-lg border border-gray-100 text-sm text-gray-700 leading-relaxed focus:outline-none focus:ring-2 focus:ring-green-500 focus:bg-white transition-all resize-y min-h-[120px]"
                            placeholder="Add detailed notes, checklists, or instructions for this task..."
                            value={selectedTask.description || ''}
                            onChange={(e) => updateTaskDescription(selectedTask.id, e.target.value)}
                        />
                     </div>
                </div>
                 <div className="p-5 bg-gray-50 border-t border-gray-100 flex justify-end gap-3">
                    <button 
                        onClick={() => setSelectedTask(null)}
                        className="px-4 py-2 rounded-lg text-sm font-medium text-gray-600 hover:bg-gray-200 transition-colors"
                    >
                        Close
                    </button>
                    <button 
                        onClick={toggleTaskCompletionFromModal}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors shadow-sm flex items-center ${selectedTask.completed ? 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-50' : 'bg-green-800 text-white hover:bg-green-900'}`}
                    >
                        <Icon name="check" className={`h-4 w-4 mr-2 ${selectedTask.completed ? 'opacity-50' : ''}`} />
                        {selectedTask.completed ? 'Mark as Incomplete' : 'Mark as Complete'}
                    </button>
                </div>
            </div>
        </div>
      )}

       <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card>
              <h4 className="font-semibold text-gray-800 mb-4 flex items-center">
                  <Icon name="document" className="h-5 w-5 text-green-700 mr-2" /> Quick Actions
              </h4>
              <div className="grid grid-cols-2 gap-4">
                  <button className="p-4 border border-green-100 rounded-xl bg-green-50 hover:bg-green-100 transition-colors text-center group">
                     <Icon name="users" className="h-6 w-6 mx-auto text-green-700 mb-2 group-hover:scale-110 transition-transform"/>
                     <span className="text-xs font-semibold text-green-900 block">Rooming List</span>
                  </button>
                  <button className="p-4 border border-green-100 rounded-xl bg-green-50 hover:bg-green-100 transition-colors text-center group">
                     <Icon name="download" className="h-6 w-6 mx-auto text-green-700 mb-2 group-hover:scale-110 transition-transform"/>
                     <span className="text-xs font-semibold text-green-900 block">Manifest (PDF)</span>
                  </button>
                  <button className="p-4 border border-green-100 rounded-xl bg-green-50 hover:bg-green-100 transition-colors text-center group">
                     <Icon name="visa" className="h-6 w-6 mx-auto text-green-700 mb-2 group-hover:scale-110 transition-transform"/>
                     <span className="text-xs font-semibold text-green-900 block">Visa Status</span>
                  </button>
                  <button className="p-4 border border-green-100 rounded-xl bg-green-50 hover:bg-green-100 transition-colors text-center group">
                     <Icon name="package" className="h-6 w-6 mx-auto text-green-700 mb-2 group-hover:scale-110 transition-transform"/>
                     <span className="text-xs font-semibold text-green-900 block">Itinerary</span>
                  </button>
              </div>
          </Card>
          <Card>
              <h4 className="font-semibold text-gray-800 mb-4 flex items-center">
                  <Icon name="alert" className="h-5 w-5 text-yellow-600 mr-2" /> Recent Activity
              </h4>
              <ul className="space-y-4">
                 <li className="flex gap-3 items-start">
                    <div className="h-2 w-2 mt-2 rounded-full bg-blue-500 flex-shrink-0"></div>
                    <div>
                       <p className="text-sm text-gray-800"><span className="font-semibold">Abdullah</span> marked <span className="italic">"Submit Visa Applications"</span> as done.</p>
                       <p className="text-xs text-gray-400 mt-0.5">2 hours ago</p>
                    </div>
                 </li>
                 <li className="flex gap-3 items-start">
                    <div className="h-2 w-2 mt-2 rounded-full bg-green-500 flex-shrink-0"></div>
                    <div>
                       <p className="text-sm text-gray-800"><span className="font-semibold">System</span> generated Manifest for Kloter A.</p>
                       <p className="text-xs text-gray-400 mt-0.5">5 hours ago</p>
                    </div>
                 </li>
                  <li className="flex gap-3 items-start">
                    <div className="h-2 w-2 mt-2 rounded-full bg-yellow-500 flex-shrink-0"></div>
                    <div>
                       <p className="text-sm text-gray-800"><span className="font-semibold">Siti</span> added new task <span className="italic">"Check Batik Inventory"</span>.</p>
                       <p className="text-xs text-gray-400 mt-0.5">Yesterday</p>
                    </div>
                 </li>
              </ul>
          </Card>
       </div>
    </div>
  );
};

