import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import PackageList from './components/PackageList';
import JamaahList from './components/JamaahList';
import OpsCenter from './components/OpsCenter';
import Finance from './components/Finance';
import Reports from './components/Reports';
import OpsBot from './components/OpsBot';
import { OpsTask } from './types';
import { MOCK_TASKS } from './constants';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState('Dashboard');
  const [isBotOpen, setIsBotOpen] = useState(false);

  // OpsCenter State (Lifted)
  const [opsTasks, setOpsTasks] = useState<OpsTask[]>(MOCK_TASKS);
  const [opsKloter, setOpsKloter] = useState('Kloter A');

  // Bot Command Handler
  const handleBotCommand = (text: string): string => {
    const lowerText = text.toLowerCase();

    // Command: Add Task
    if (lowerText.startsWith('add task') || lowerText.startsWith('create task')) {
      const title = text.replace(/add task|create task/i, '').trim();
      if (!title) return "Please specify a task title. E.g., 'Add task Buy Zamzam water'";

      const newTask: OpsTask = {
        id: Date.now().toString(),
        title: title,
        category: 'Pre-Departure', // Default category
        dueDate: new Date().toISOString().split('T')[0],
        completed: false,
        assignee: 'Bot',
        priority: 'Medium',
        description: 'Created via OpsBot command.'
      };

      setOpsTasks(prev => [...prev, newTask]);
      // If we are not in Ops view, switch to it? Optional, but helpful.
      if (activeView !== 'Operasional') setActiveView('Operasional');
      return `Task "${title}" added successfully to Pre-Departure checklist.`;
    }

    // Command: Complete Task
    if (lowerText.startsWith('complete') || lowerText.startsWith('finish') || lowerText.startsWith('mark done')) {
      const search = text.replace(/complete|finish|mark done/i, '').trim();
      const taskIndex = opsTasks.findIndex(t => t.title.toLowerCase().includes(search.toLowerCase()));

      if (taskIndex >= 0) {
        const task = opsTasks[taskIndex];
        const updatedTasks = [...opsTasks];
        updatedTasks[taskIndex] = { ...task, completed: true };
        setOpsTasks(updatedTasks);
        return `Task "${task.title}" has been marked as completed.`;
      }
      return `I couldn't find a task matching "${search}".`;
    }

    // Command: Switch Kloter
    if (lowerText.includes('switch to kloter') || lowerText.includes('show kloter')) {
      if (lowerText.includes('kloter a')) {
        setOpsKloter('Kloter A');
        setActiveView('Operasional');
        return "Switched view to Kloter A.";
      }
      if (lowerText.includes('kloter b')) {
        setOpsKloter('Kloter B');
        setActiveView('Operasional');
        return "Switched view to Kloter B.";
      }
      if (lowerText.includes('kloter c')) {
        setOpsKloter('Kloter C');
        setActiveView('Operasional');
        return "Switched view to Kloter C.";
      }
      return "Please specify Kloter A, B, or C.";
    }

    // Command: Status Report
    if (lowerText.includes('status') || lowerText.includes('report')) {
      const total = opsTasks.length;
      const completed = opsTasks.filter(t => t.completed).length;
      return `Current Operations Status for ${opsKloter}: ${completed}/${total} tasks completed.`;
    }

    if (lowerText.includes('hello') || lowerText.includes('hi')) {
        return "Assalamualaikum! I can help you manage operations. Try 'Add task [name]', 'Complete [task]', or 'Show Kloter A'.";
    }

    return "I didn't quite get that. You can ask me to 'Add task', 'Complete task', or 'Switch to Kloter'.";
  };

  const renderView = () => {
    switch (activeView) {
      case 'Dashboard':
        return <Dashboard />;
      case 'Paket & Penjualan':
        return <PackageList />;
      case 'Jamaah':
        return <JamaahList />;
      case 'Operasional':
        return (
          <OpsCenter 
            tasks={opsTasks} 
            setTasks={setOpsTasks} 
            selectedKloter={opsKloter} 
            setSelectedKloter={setOpsKloter} 
          />
        );
      case 'Keuangan':
        return <Finance />;
      case 'Laporan':
        return <Reports />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="bg-gray-100 min-h-screen flex text-gray-800">
      <Sidebar activeView={activeView} setActiveView={setActiveView} />
      <div className="flex-1 flex flex-col">
        <Header travelName="Al-Haramain Travel (White-Label)" />
        <main className="p-6 lg:p-8 flex-1 overflow-y-auto">
          {renderView()}
        </main>
      </div>
      <OpsBot 
        isOpen={isBotOpen} 
        setIsOpen={setIsBotOpen} 
        onCommand={handleBotCommand}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Card } from './shared/Card';
import { Icon } from './shared/Icon';
import { OpsTask, TaskCategory, TaskPriority } from '../types';
import { TEAM_MEMBERS } from '../constants';

interface OpsCenterProps {
  tasks: OpsTask[];
  setTasks: React.Dispatch<React.SetStateAction<OpsTask[]>>;
  selectedKloter: string;
  setSelectedKloter: (kloter: string) => void;
}

const OpsCenter: React.FC<OpsCenterProps> = ({ tasks, setTasks, selectedKloter, setSelectedKloter }) => {
  const [activeTab, setActiveTab] = useState<TaskCategory>('Pre-Departure');
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskAssignee, setNewTaskAssignee] = useState('Abdullah');
  const [newTaskPriority, setNewTaskPriority] = useState<TaskPriority>('Medium');
  const [selectedTask, setSelectedTask] = useState<OpsTask | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'priority'>('date');

  const filteredTasks = tasks.filter(t => t.category === activeTab);

  const sortedTasks = [...filteredTasks].sort((a, b) => {
    if (sortBy === 'priority') {
        const priorityOrder: { [key in TaskPriority]: number } = { High: 3, Medium: 2, Low: 1 };
        if (priorityOrder[b.priority] !== priorityOrder[a.priority]) {
            return priorityOrder[b.priority] - priorityOrder[a.priority];
        }
    }
    // Fallback to date sort or if sortBy is 'date'
    return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
  });

  const toggleTask = (id: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
    if (selectedTask && selectedTask.id === id) {
        setSelectedTask(prev => prev ? { ...prev, completed: !prev.completed } : null);
    }
  };

  const updateTaskAssignee = (id: string, newAssignee: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, assignee: newAssignee } : t));
    if (selectedTask && selectedTask.id === id) {
        setSelectedTask(prev => prev ? { ...prev, assignee: newAssignee } : null);
    }
  };

  const updateTaskDescription = (id: string, newDescription: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, description: newDescription } : t));
    if (selectedTask && selectedTask.id === id) {
        setSelectedTask(prev => prev ? { ...prev, description: newDescription } : null);
    }
  };

  const updateTaskPriority = (id: string, newPriority: TaskPriority) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, priority: newPriority } : t));
    if (selectedTask && selectedTask.id === id) {
        setSelectedTask(prev => prev ? { ...prev, priority: newPriority } : null);
    }
  };

  const addTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    const newTask: OpsTask = {
      id: Date.now().toString(),
      title: newTaskTitle,
      category: activeTab,
      dueDate: new Date().toISOString().split('T')[0],
      completed: false,
      assignee: newTaskAssignee,
      priority: newTaskPriority,
      description: ''
    };

    setTasks([...tasks, newTask]);
    setNewTaskTitle('');
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
    if (selectedTask?.id === id) setSelectedTask(null);
  };

  const calculateProgress = (category: TaskCategory) => {
    const categoryTasks = tasks.filter(t => t.category === category);
    if (categoryTasks.length === 0) return 0;
    const completed = categoryTasks.filter(t => t.completed).length;
    return Math.round((completed / categoryTasks.length) * 100);
  };

  const toggleTaskCompletionFromModal = () => {
      if (!selectedTask) return;
      toggleTask(selectedTask.id);
  };

  const getPriorityColor = (priority: TaskPriority) => {
      switch (priority) {
          case 'High': return 'bg-red-100 text-red-800 border-red-200';
          case 'Medium': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
          case 'Low': return 'bg-blue-100 text-blue-800 border-blue-200';
          default: return 'bg-gray-100 text-gray-800';
      }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-bold text-green-900">Operations Center</h2>
           <p className="text-gray-500 text-sm">Manage logistics, checklists, and workflows for your groups.</p>
        </div>
        <div className="flex items-center bg-white rounded-lg shadow-sm px-3 py-2 border border-gray-200">
           <Icon name="users" className="h-5 w-5 text-gray-500 mr-2" />
           <select 
             value={selectedKloter} 
             onChange={(e) => setSelectedKloter(e.target.value)}
             className="bg-transparent border-none focus:ring-0 text-gray-700 font-medium text-sm outline-none cursor-pointer"
           >
             <option value="Kloter A">Kloter A - 15 Mar 2025</option>
             <option value="Kloter B">Kloter B - 20 Apr 2025</option>
             <option value="Kloter C">Kloter C - 10 Jun 2025</option>
           </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {(['Pre-Departure', 'In-Saudi', 'Post-Return'] as TaskCategory[]).map(cat => {
            const progress = calculateProgress(cat);
            const isActive = activeTab === cat;
            return (
             <Card key={cat} className={`cursor-pointer transition-all hover:shadow-lg ${isActive ? 'ring-2 ring-green-500 bg-green-50/50' : ''}`} >
                <div onClick={() => setActiveTab(cat)}>
                   <div className="flex justify-between items-start mb-4">
                      <h3 className={`font-semibold ${isActive ? 'text-green-900' : 'text-gray-700'}`}>{cat}</h3>
                      {isActive && <div className="h-2 w-2 rounded-full bg-green-500"></div>}
                   </div>
                   <div className="flex items-end justify-between">
                      <span className="text-3xl font-bold text-green-800">{progress}%</span>
                      <span className="text-xs text-gray-500 mb-1">Completed</span>
                   </div>
                   <div className="w-full bg-gray-200 rounded-full h-1.5 mt-3">
                      <div className="bg-green-600 h-1.5 rounded-full transition-all duration-500" style={{ width: `${progress}%` }}></div>
                   </div>
                </div>
             </Card>
        )})}
      </div>

      <Card>
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-6 gap-4">
           <h3 className="text-lg font-bold text-gray-800 flex items-center">
              <span className="bg-green-100 p-1.5 rounded-md mr-3">
                 <Icon name="ops" className="h-5 w-5 text-green-700"/>
              </span>
              {activeTab} Checklist
           </h3>
           <div className="flex items-center space-x-2">
                <div className="flex items-center bg-gray-50 border border-gray-200 rounded-lg p-1 mr-2">
                   <button 
                      onClick={() => setSortBy('date')} 
                      className={`text-xs px-2 py-1 rounded transition-colors ${sortBy === 'date' ? 'bg-white shadow-sm text-green-800 font-medium' : 'text-gray-500 hover:text-gray-700'}`}
                   >
                     Date
                   </button>
                   <button 
                      onClick={() => setSortBy('priority')} 
                      className={`text-xs px-2 py-1 rounded transition-colors ${sortBy === 'priority' ? 'bg-white shadow-sm text-green-800 font-medium' : 'text-gray-500 hover:text-gray-700'}`}
                   >
                     Priority
                   </button>
                </div>
                <span className="text-xs font-medium text-gray-500 px-3 py-1 bg-gray-100 rounded-full">
                    {filteredTasks.filter(t => t.completed).length}/{filteredTasks.length} Done
                </span>
           </div>
        </div>

        <form onSubmit={addTask} className="flex flex-col md:flex-row gap-3 mb-6 bg-gray-50 p-4 rounded-lg border border-gray-100">
           <div className="flex-1">
               <input 
                type="text" 
                placeholder="What needs to be done?" 
                className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-green-500 focus:border-transparent text-sm"
                value={newTaskTitle}
                onChange={(e) => setNewTaskTitle(e.target.value)}
                />
           </div>
           <div className="flex gap-2 w-full md:w-auto">
               <select
                    value={newTaskPriority}
                    onChange={(e) => setNewTaskPriority(e.target.value as TaskPriority)}
                    className="border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-green-500 focus:border-transparent text-sm bg-white cursor-pointer"
                >
                    <option value="Low">Low</option>
                    <option value="Medium">Medium</option>
                    <option value="High">High</option>
                </select>
               <select
                    value={newTaskAssignee}
                    onChange={(e) => setNewTaskAssignee(e.target.value)}
                    className="border border-gray-300 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-green-500 focus:border-transparent text-sm bg-white cursor-pointer"
                >
                    {TEAM_MEMBERS.map(member => (
                    <option key={member} value={member}>{member}</option>
                    ))}
                </select>
               <button type="submit" className="bg-green-800 text-white px-4 py-2 rounded-lg hover:bg-green-900 transition-colors flex items-center justify-center text-sm font-medium whitespace-nowrap">
                  <Icon name="add" className="h-4 w-4 mr-1" /> Add Task
               </button>
           </div>
        </form>

        <div className="space-y-3">
           {sortedTasks.length === 0 ? (
               <div className="text-center py-12 border-2 border-dashed border-gray-100 rounded-xl">
                  <Icon name="document" className="h-10 w-10 text-gray-300 mx-auto mb-2" />
                  <p className="text-gray-400 text-sm">No tasks found for this phase.</p>
               </div>
           ) : (
               sortedTasks.map(task => (
                   <div key={task.id} className={`flex items-center p-3 rounded-lg border transition-all group ${task.completed ? 'bg-gray-50 border-gray-100' : 'bg-white border-gray-200 hover:border-green-300 shadow-sm'}`}>
                       <button 
                         onClick={(e) => {
                             e.stopPropagation();
                             toggleTask(task.id);
